window.S17Page={"sceneId":"co3","caseId":"s17x-co3-tubing-stress","name":"完井管柱受力智能分析","title":"完井管柱受力智能分析","summary":"沿 2500 m 管柱对照轴向、环向与等效应力，切换温度约束，理解为何简单拉力基线会遗漏风险。","directory":"expansion-cases","caseVersion":"1.1.0","portalHref":"../../../../portal/index.html","referenceHref":"../../../../portal/reference/fluorescence.html"};
